/**
 * Cria pedido e baixa estoque em uma transação.
 * Lança erro se estoque insuficiente ou produto não existir.
 */
function criarPedido(produtoId, quantidade) {
  const tx = db.transaction((pid, qtd) => {
    // 1. Trava a linha do produto (SELECT ... FOR UPDATE não existe no SQLite,
    // mas a transação serializada garante consistência)
    const produto = db.prepare('SELECT estoque FROM produtos WHERE id = ?').get(pid);
    if (!produto) throw new Error('Produto não encontrado');
    if (produto.estoque < qtd) throw new Error('Estoque insuficiente');

    // 2. Baixa o estoque
    db.prepare('UPDATE produtos SET estoque = estoque - ? WHERE id = ?').run(qtd, pid);

    // 3. Registra o pedido
    const info = db.prepare(
      'INSERT INTO pedidos (produto_id, quantidade) VALUES (?, ?)'
    ).run(pid, qtd);

    return { pedidoId: info.lastInsertRowid, produtoId: pid, quantidade: qtd };
  });

  return tx(produtoId, quantidade);
}

