Pontos-chave:
- `db.transaction(fn)` executa `fn` dentro de `BEGIN IMMEDIATE ... COMMIT/ROLLBACK`. Se `fn` lançar exceção, faz rollback automático.
- `BEGIN IMMEDIATE` adquire lock de escrita logo no início, evitando deadlocks simples em concorrência leve.
- Valide estoque **dentro** da transação, depois do `SELECT`, para evitar race condition.
- Se preferir API assíncrona (`sqlite3` ou `better-sqlite3` com wrapper), a lógica é a mesma: `BEGIN`, operações, `COMMIT`/`ROLLBACK` em `try/catch`.

### Passos principais

1. **Abrir a conexão** com o banco SQLite usando um driver (por exemplo, `sqlite3` ou `better-sqlite3`).  
2. **Iniciar uma transação** para garantir que a inserção do pedido e a atualização do estoque ocorram juntas – se alguma falhar, tudo é revertido.  
3. **Inserir o pedido** na tabela `orders` (ou `pedidos`).  
4. **Atualizar o estoque** do(s) produto(s) relacionado(s) na tabela `products`.  
5. **Commit** da transação se tudo deu certo; caso contrário, **rollback**.

### Exemplo completo (usando `sqlite3` – API assíncrona)

```js
// npm i sqlite3
const sqlite3 = require('sqlite3').verbose();
const db = new sqlite3.Database('./loja.db');

// Função que salva um pedido e atualiza o estoque
function criarPedido(pedido) {
  // pedido = { clienteId, itens: [{ produtoId, quantidade, precoUnitario }, ...] }
  return new Promise((resolve, reject) => {
    db.serialize(() => {
      db.run('BEGIN TRANSACTION');

      // 1️⃣ Inserir o pedido (tabela orders)
      const insertOrderSql = `
        INSERT INTO orders (cliente_id, data, total)
        VALUES (?, datetime('now'), ?)
      `;
      const totalPedido = pedido.itens.reduce(
        (acc, i) => acc + i.quantidade * i.precoUnitario,
        0
      );

      db.run(insertOrderSql, [pedido.clienteId, totalPedido], function (err) {
        if (err) {
          db.run('ROLLBACK');
          return reject(err);
        }

        const orderId = this.lastID; // ID do pedido recém‑criado

        // 2️⃣ Inserir os itens do pedido (tabela order_items)
        const insertItemSql = `
          INSERT INTO order_items (order_id, product_id, quantity, unit_price)
          VALUES (?, ?, ?, ?)
        `;

        const stmtItem = db.prepare(insertItemSql);
        for (const item of pedido.itens) {
          stmtItem.run([orderId, item.produtoId, item.quantidade, item.precoUnitario]);
        }
        stmtItem.finalize(err => {
          if (err) {
            db.run('ROLLBACK');
            return reject(err);
          }

          // 3️⃣ Atualizar o estoque dos produtos
          const updateStockSql = `
            UPDATE products
            SET stock = stock - ?
            WHERE id = ? AND stock >= ?
          `;

          const stmtStock = db.prepare(updateStockSql);
          for (const item of pedido.itens) {
            stmtStock.run([item.quantidade, item.produtoId, item.quantidade], function (err) {
              if (err) {
                db.run('ROLLBACK');
                return reject(err);
              }
              if (this.changes === 0) {
                // Não houve atualização → estoque insuficiente
                db.run('ROLLBACK');
                return reject(
                  new Error(`Estoque insuficiente para o produto ${item.produtoId}`)
                );
              }
            });
          }
          stmtStock.finalize(err => {
            if (err) {
              db.run('ROLLBACK');
              return reject(err);
            }

            // 4️⃣ Tudo ok → commit
            db.run('COMMIT', commitErr => {
              if (commitErr) return reject(commitErr);
              resolve({ orderId, total: totalPedido });
            });
          });
        });
      });
    });
  });
}

// Exemplo de uso
